   194                                  slen = decode_tlv(ctx, &child_cursor, fr_dict_by_da(child), child, p, end - p, decode_ctx);
   195                                  if (slen < 0) goto unknown;
   196                                  p += slen;
   197                          }
   198
   199                          goto done;
   200                  }
   201
   202                  child_length = child->flags.length;
   203
   204                  /*
   205                   *      If this field overflows the input, then *all*
   206                   *      of the input is suspect.
   207                   */
   208                  if ((p + child_length) > end) {
   209                          FR_PROTO_TRACE("fr_struct_from_network - child length %zd overflows buffer", child_length);
   210                          goto unknown;
   211                  }
   212
   213                  if (!child_length) child_length = (end - p);
   214
   215                  /*
   216                   *      Magic values get the callback called.
   217                   *
   218                   *      Note that if this is an *array* of DNS labels,
   219                   *      the callback should deal with this.
   220                   */
   221                  if (decode_value) {
   222                          ssize_t slen;
   223
   224                          slen = decode_value(ctx, &child_cursor, fr_dict_by_da(child), child, p, child_length, decode_ctx);
   225                          if (slen < 0) return slen - (p - data);
