   238                  default:
   239                          FR_PROTO_TRACE("fr_struct_from_network - unknown child type");
   240                          goto unknown;
   241
   242                  case FR_TYPE_LEAF:
   243                          break;
   244                  }
   245
   246                  vp = fr_pair_afrom_da(ctx, child);
   247                  if (!vp) {
   248                          FR_PROTO_TRACE("fr_struct_from_network - failed allocating child VP");
   249                          goto unknown;
   250                  }
   251
   252                  /*
   253                   *      No protocol-specific data types here (yet).
   254                   *
   255                   *      If we can't decode this field, then the entire
   256                   *      structure is treated as a raw blob.
   257                   */
   258                  if (fr_value_box_from_network(vp, &vp->data, vp->da->type, vp->da, p, child_length, true) < 0) {
   259                          FR_PROTO_TRACE("fr_struct_from_network - failed decoding child VP");
   260                          talloc_free(vp);
   261                  unknown:
   262                          fr_pair_list_free(&head);
   263
   264                          vp = fr_raw_from_network(ctx, parent, data, data_len);
   265                          if (!vp) return -1;
   266
   267                          /*
   268                           *      And append this one VP to the output cursor.
   269                           */
   270                          fr_dcursor_append(cursor, vp);
   271                          return data_len;
   272                  }
   273
   274                  vp->type = VT_DATA;
   275                  vp->vp_tainted = true;
   276                  fr_dcursor_append(&child_cursor, vp);
   277
   278                  if (fr_dict_attr_is_key_field(vp->da)) key_vp = vp;
   279
   280                  /*
   281                   *      Note that we're decoding fixed fields here.
   282                   *      So we skip the input based on the *known*
   283                   *      length, and not on the *decoded* length.
   284                   */
   285                  p += child_length;
   286                  child_num++;    /* go to the next child */
   287          }
   288
   289          /*
   290           *      Is there a substructure after this one?  If so, go
   291           *      decode it.
   292           */
   293          if (key_vp) {
   294                  ssize_t slen;
   295                  fr_dict_enum_t const *enumv;
   296                  child = NULL;
   297
   298                  FR_PROTO_HEX_DUMP(p, (end - p), "fr_struct_from_network - substruct");
   299
   300                  /*
   301                   *      Nothing more to decode, don't decode it.
   302                   */
   303                  if (p >= end) goto done;
   304
   305                  enumv = fr_dict_enum_by_value(key_vp->da, &key_vp->data);
   306                  if (enumv) child = enumv->child_struct[0];
   307
   308                  if (!child) {
   309                  unknown_child:
   310                          /*
   311                           *      Encode the unknown child as attribute
   312                           *      number 0.  This choice means we don't
   313                           *      have to look up, or keep track of, the
   314                           *      number of children of the key field.
   315                           */
   316                          child = fr_dict_unknown_afrom_fields(ctx, key_vp->da,
   317                                                               fr_dict_vendor_num_by_da(key_vp->da), 0);
   318                          if (!child) goto unknown;
   319
   320                          vp = fr_raw_from_network(ctx, child, p, end - p);
   321                          if (!vp) {
   322                                  fr_dict_unknown_free(&child);
   323                                  return -(p - data);
   324                          }
   325
   326                          fr_dcursor_append(&child_cursor, vp);
   327                          p = end;
   328                  } else {
   329                          fr_assert(child->type == FR_TYPE_STRUCT);
   330
   331                          slen = fr_struct_from_network(ctx, &child_cursor, child, p, end - p,
   332                                                        decode_ctx, decode_value, decode_tlv);
   333                          if (slen <= 0) goto unknown_child;
   334                          p += slen;
   335                  }
   336
   337                  fr_dict_unknown_free(&child);
   338
   339                  fr_dcursor_head(&child_cursor);
   340                  fr_dcursor_tail(cursor);

340                  fr_dcursor_tail(cursor);
   341                  fr_dcursor_merge(cursor, &child_cursor);        /* Wind to the end of the new pairs */
   342
   343                  /*
   344                   *      Else return whatever we decoded.  Note that if
   345                   *      the substruct ends in a TLV, we decode only
   346                   *      the fixed-length portion of the structure.
   347                   */
   348                  return p - data;
   349          }
   350
   351  done:
   352          fr_dcursor_head(&child_cursor);
   353          fr_dcursor_tail(cursor);
   354          fr_dcursor_merge(cursor, &child_cursor);        /* Wind to the end of the new pairs */
   355
   356          return data_len;
   357  }
